using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra;

internal sealed class PBOriginalReadoutRealizationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Cone-positive functionals and actual finite matrix corners read the whole original directed two-table; a single ambient state also supplies coherent central-sector outer budgets.",
        H("Original labels, positive two-tables, and a selected central sector"),
        Blocks(Describe.Lean(DescribeId.Create("original-positive-readings"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/PBOriginalReadoutRealization.original_positive_readings"),
            H("Whole directed tables and actual finite matrix corners"),
            StatementSource.FromAuthor(Disp(PositiveStatement())), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let C be any subset of the original real normed space E detected exactly by all original real-linear evaluations p. J is the original bilinear Jordan product and D is the same arbitrary total function. Suppose every original directed two-table is positive semidefinite. Every C-positive real-linear functional f then reads the whole directed table positively, for every original pair and every complex test vector. Its determinant gives the stated quadratic budget. No nonzero, unit-mass or continuity premise is imposed on f or the original evaluations. The proof uses the positive quadratic original label and the exact cone, rather than an extension to an ambient associative algebra.")),
                Paragraph(Text("A consequence for the original unit row uses an arbitrary real normed E, which need not be complete, and an arbitrary complete real normed X with raw six-law JB data (JX,uX). Let i:E->X be the same dense real linear isometry, with i(u)=uX and i(J(a,b))=JX(i(a),i(b)). Assume that the actual square cone {a: there exists y in X with JX(y,y)=i(a)} is detected exactly by the unchanged original evaluation family, that this family separates E, and that every actual directed original two-table is positive semidefinite. Retain the same arbitrary total D:E times E->E and full PB: for nu=D(a,b)-J(a,c) and omega=J(a,b)+D(a,c), D(b+nu,c+omega)-D(b-nu,c-omega)=-2(J(b,nu)+J(c,omega)). Then D(s u,b)=0 for every real s whenever i(b) or i(-b) is an actual square in X. All original evaluation masses and zero inputs remain in scope.")),
                Paragraph(Text("For a nonzero h=D(s u,b), the raw JB construction in JBComplexification supplies a positive unital norm-supporting beta on X. Put f=beta composed with i and Z=f(h). The ambient square bound at uX and positive_table_transfer give f(J(h,h))=Z squared and f(J(h-Z u,h-Z u))=0. Applying the same determinant inequality to this null vector shows f(J(h,x))=Z f(x) for every original x. Set k=s Z/(1+s squared), nu=h-sk u and omega=s b. Original P2 and separation give D(s u,k u)=0. The two literal PB outer pairs satisfy (k u+omega)-s(b+nu)=-s(h-Z u) and (k u-omega)+s(b-nu)=-s(h-Z u). Their determinant budgets vanish, so both actual outer D readings vanish. The PB difference yields f(J(b,h))=0, and Z nonzero yields f(b)=0.")),
                Paragraph(Text("For the semidefinite b, choose v=i(b) or i(-b) and a square root y in X with JX(y,y)=v. The ambient upper square bound at y is norm(y) squared uX-v. Applying quadratic_preserves_squares with parameter y gives norm(y) squared v-JX(v,v) as an actual square; the Jordan identity identifies this expression. Positivity and beta(v)=0 force beta(JX(v,v))=0, hence f(J(b,b))=0 in either sign case. The original determinant bound at (s u,b) then forces f(h)=0, contradicting norm support. Every D call stays on E. This proves the semidefinite second-input unit row only; the general unit row still requires the separate pure-state approximation and subsequent two-generator argument. It supplies neither an extension of D nor the later polynomial or spectral conclusions.")),
                Paragraph(Text("originalCorner(i,JX,k) is exactly the original inclusion inverse image of the Peirce two-space ker(JX(i(k))-id). Thus its elements are literally original labels in E intersect X two(k). ActualMatrixCorner supplies the source's closed-corner interface: an isometric original inclusion, inherited Jordan multiplication, the original k as corner unit, closure under J and the same D, and a real-linear equivalence onto all self-adjoint complex matrices. The equivalence preserves the inherited norm using the matrix L2 operator norm, the unit, the Jordan product, and the exact inherited cone. This is a conditional interface, not a construction from abstract JB axioms. Density and completeness of a real JB completion are not needed once this actual finite interface is supplied.")),
                Paragraph(Text("cornerJordan and cornerResponse are literal restrictions: their underlying original labels are J(a,b) and D(a,b). Every original evaluation restricts by composition with the original subtype inclusion, so exact-cone detection and all original directed tables restrict without changing preparations or their masses. The matrix equivalence is onto the whole finite self-adjoint matrix space; no proper surrogate matrix subsystem is substituted.")),
                Paragraph(Text("cornerOp is ordinary matrix action on EuclideanSpace over the complex scalars. cornerVectorRead is the real part of the vector expectation, is real linear and nonnegative on the inherited cone, and its complex expectation is real. It reads k as the squared Euclidean norm, J(a,a) as the squared Euclidean norm of a acting on the vector, and J(a,b) as the real inner product of the two resulting vectors. Whole-table transfer and the determinant give the budget on the literal original D(a,b). The index type may be empty and the vector may be zero. The zero corner and k=0 remain in scope whenever the supplied interface exists; no ambient extension, GNS representation or normalized vector is used."))),
            DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-piecewise"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/PBOriginalReadoutRealization.original_piecewise"),
            H("Coherent realization with zero and nonzero axis branches"),
            StatementSource.FromAuthor(Disp(Statement())), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("OriginalData retains the original real normed label space E, its bilinear Jordan product J, unit u, and arbitrary total response D:E times E to E. Its supplied inclusion i into an arbitrary unital complex C-star algebra A is real linear, isometric and self-adjoint valued, maps u to one, and satisfies i(J(a,b))=(i(a)i(b)+i(b)i(a))/2. E need not be complete or dense in the whole self-adjoint part of A. The original preparation family is arbitrary and its cone is exact: i(a) is positive exactly when every original preparation evaluates a nonnegatively. Every original directed Hermitian two-table is positive semidefinite. No mass is divided or normalized; zero, unequal and subnormalized original masses remain in the domain.")),
                Paragraph(Text("For every vector v in the closed cyclic subspace, vectorRead is the real expectation of the original label in the ambient GNS representation. Positivity of a C-star square makes this a positive functional on the exact original cone. compressed_p2 applies the universal positive-functional clause of original_positive_readings to this functional and takes its determinant bound. The compression inner-product identity identifies that bound with Readout.p2 for every original pair. actual_outer_budget uses this same P2 field at its constructed supporting vector for both actual outer D calls; its finite estimate therefore uses the positive-reading supply. The finite matrix-corner clause is a separate application and is not needed for this C-star compression.")),
                Paragraph(Text("B and C are unital star subalgebras of the same A, C is norm closed, C is contained in B, and every element of C commutes with every element of B. The theorem accepts a specified unital star character chi:C to the complex scalars. Its existence forces this character branch to be proper. Hahn-Banach extends the continuous character functional with its norm preserved. Norm one and value one imply positivity, giving one ambient state phi which retains this chi. The original normalized_gns declaration supplies the norm-one cyclic vector in the completed GNS space. No independent extension is selected for each reading vector.")),
                Paragraph(Text("cyclicSpace(phi,B) is the norm closure of the range of b mapped to pi(b)xi in that one ambient GNS representation. It contains xi and is B invariant. For c in C, retention makes pi(c-chi(c)one)xi have zero squared norm. Centrality propagates this equality along the B orbit and continuity passes it to its closed span, so pi(c)v=chi(c)v for every vector in cyclicSpace. Its real Hilbert space is nontrivial because xi has norm one.")),
                Paragraph(Text("compressedOp sends every original a in E to the orthogonal compression of pi(i(a)) to that single cyclicSpace, regarded as a real linear operator. This map is linear and symmetric on all original labels, including unknown outer D outputs. It reads u as the identity. The known Jordan domain is exactly L=i inverse image of B; invariance proves the Jordan law there. No closure, descent, additivity, homogeneity or extension of D is introduced.")),
                Paragraph(Text("For the common-extension step in the original 217–218 argument, fix the same original a,b,d=D(a,b) and let B be the norm closure in A of the unital star algebra generated by i(a),i(b),i(d). Let fB be any positive continuous complex-linear functional on B. Hahn-Banach gives a complex-linear ambient extension g of equal norm. Since the inclusion preserves one and positivity gives norm(fB)=fB(one), the extension satisfies norm(g)=g(one); the positive-functional norm criterion makes g positive. This construction preserves the entire functional and its mass, including zero, without dividing by that mass. The real functional f on the original E is Re(g(i(e))). original_positive_readings applies to this one f at every original pair. Applying the same f to full PB reads both literal outer calls D(b+nu,c+omega) and D(b-nu,c-omega), even when their images lie outside B. Orthogonal compression gives these same expectations on cyclicSpace. Neither the original preparation family nor the response map is extended.")),
                Paragraph(Text("The separate irreducible-family route starts with each pure state of this B. A positive ambient extension need not be pure on A. Its B orbit closure, equipped with the restricted ambient operators and the same cyclic vector, must instead be identified with the GNS triplet of the original B state. GNS uniqueness then transfers topological irreducibility to this closed cyclic space. The family of all pure B states separates B; applying the original isometric inclusion returns any vanishing original label to E. The required external Lean sources are kencyke/quantum-system at revision 5d67fe8030eaf1bdaf081e2acfcbe3fbaecfda7c, GNS.Representation.isPure_iff_isIrreducible and GNS.DirectSum.pureStateFamily_separatesPoints. These sources are outside this module's canonical import closure. Accordingly original_piecewise certifies the central-character realization stated above, while admission of the additional irreducible-family bridge remains separate. No finite-dimensional, separability or faithful-single-state assumption supplies this step, and the step supplies neither Pauli coordinates nor the original square saturation.")),
                Paragraph(Text("In this same supplied JC carrier, raw directed P2 and the exact cone already imply D(a,r a)=0 for every real r: the transferred determinant is zero on proportional pairs, and the original preparations separate by cone antisymmetry and the isometric inclusion. This includes both zero rows. Suppose now that J(a,b)=0 and d=D(a,b). PB at (a,b,0) has inner labels d and zero, so its two literal outer D values vanish and J(b,d)=0. Hermitian skewness, commutativity of J and the exchanged substitution give J(a,d)=0. The three actual images i(a),i(b),i(d) therefore pairwise anticommute. Each of their squares commutes with every generator and its adjoint. The closed double-centralizer inclusion for the topological star adjoin then makes each square commute with all of B. In every nonnull topologically irreducible representation of this actual B, CStarRep.isIrreducible_iff_centralizer in the same pinned external source makes the three represented squares scalar. Self-adjointness and a unit-vector expectation make those scalars nonnegative real squares. This applies to the actual pure-B cyclic family above and uses no finite dimension, separability, prescribed Pauli labels or purity of the ambient extension. These applications remain outside this module's canonical import closure. They do not supply the local original value D(a,t u+lambda a)=0 needed in actual_outer_budget, its full BDerivedInterface, or the equality between the represented d square and the product of the represented a and b squares.")),
                Paragraph(Text("The same actual cyclic space also retains the degenerate branch without affine-zero input. For an arbitrary vector v, the vector functional of the initial ambient extension reads every original label and its P2 determinant. If either represented original a or b is zero and J(a,b)=0, that determinant forces the diagonal reading of d to vanish for every v. Symmetry then makes the represented d zero. A vanishing square radius X or Y makes its self-adjoint axis zero, so the actual represented difference d squared minus a squared times b squared is zero in this branch. No vector mass is divided in this argument. For the exact return to E, anticommutation makes the represented a and b squares commute, and the original inclusion sends J(d,d)-J(J(a,a),J(b,b)) to i(d) squared minus i(a) squared times i(b) squared. If this same difference vanishes in every member of the actual pure-B cyclic family, its existing separation theorem and the same isometric inclusion return the original difference as zero. This last implication leaves the nonzero-radius premise unpaid; it does not identify the two square scalars or establish original square saturation.")),
                Paragraph(Text("For complex coefficients z and w, the original quadratic label is normSq(z)J(a,a)+normSq(w)J(b,b)+2 Re(conjugate(z)w)J(a,b)+2 Im(conjugate(z)w)D(a,b). Hermitian original tables determine the reversed readings. Their positivity and the exact original cone make this label positive in A. Every mathematical positive functional therefore reads the same whole two-table positively. The determinant gives f(D(a,b)) squared at most f(J(a,a))f(J(b,b))-f(J(a,b)) squared. Applying this to the actual ambient vector expectation and then the compression proves Readout.p2 for every pair of original labels and every vector, including zero. Mathematical vector expectations are not identified with original preparations.")),
                Paragraph(Text("SectorCertificate contains six actual elements xx,yy,dd,xy,xd,yd of C, wired respectively to i(J(x,x)), i(J(y,y)), i(J(D(x,y),D(x,y))), i(J(x,y)), i(J(x,D(x,y))) and i(J(y,D(x,y))). It requires the original x,y,D(x,y) to lie in L. The specified character reads the first three as X squared, Y squared and delta squared, and the last three as zero. Scalarization and the local Jordan law prove the represented square and anticommutation relations. Global ambient anticommutation is not a premise: the three central cross elements may be nonzero globally.")),
                Paragraph(Text("When X=0 or Y=0, raw all-vector P2 forces every diagonal expectation of op(D(x,y)) to vanish. Symmetry makes that operator zero, and its represented square on the nontrivial cyclic space gives delta=0. This branch uses no involutions. When X and Y are both nonzero, normalize only the mathematical represented axes by real scalars to construct Fibre of the same Readout. X and Y may be unequal and delta may be zero. This normalization supplies no new original input, physical inverse or operation.")),
                Paragraph(Text("The nonzero branch directly applies PBActualOuterBudget.actual_outer_budget to this constructed R and Fibre, the same original J,u,D,x,y, original PB and the complete six-field BDerivedInterface. For every real lambda,t with t nonzero and t squared=lambda squared X squared+1, write z=t u+lambda x, nu=D(x,y)-J(x,z), omega=J(x,y)+D(x,z). It obtains one unit vector reading both actual outer original labels D(y+nu,z+omega) and D(y-nu,z-omega), each with squared budget X squared/t squared+delta squared, their difference 2 lambda X squared Y/t, and lambda squared X squared(X squared Y squared-delta squared) at most X squared+delta squared. Omega may be globally nonzero; only its operator reading is killed. Unknown outer D outputs remain original labels and need not belong to L.")),
                Paragraph(Text("For the zero algebra A, faithfulness makes every original label and every original D value zero, independently of a character or normalized state. This is the first conjunct of the theorem. The second conjunct constructs the specified-character realization whenever its premises are supplied.")),
                Paragraph(Text("The realization theorem assumes a supplied complex C-star carrier, SectorCertificate and the six-field BDerivedInterface. It does not construct that carrier from an abstract real JB algebra, exclude Albert factors, derive the certificate or interface from original PB or orthogonality, or prove global response reconstruction, saturation or separation. The positive-reading theorem needs only the exact original cone and the original directed two-tables; its finite matrix conclusions additionally assume ActualMatrixCorner. Neither theorem constructs the real JB completion or the actual closed original-response corner from the original axioms."))),
            DescribeRole.Theorem))));

    private static Formula I(string s) => F.Id(s);
    private static Formula C(string s, params Formula[] a) => global::StrataLint.Scribe.DefinitionDsl.Call(s,a);
    private static Formula N(int n) => global::StrataLint.Scribe.DefinitionDsl.Num(n);
    private static Formula All(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll,FormulaIdentifier.Create(s),t,b);
    private static Formula Eq(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Equal(a,b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.And,b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.Implies,b);
    private static Formula Mul(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Multiply(a,b);
    private static Formula Inst(Formula a, Formula b) => Seq(OpenBracket,a,CloseBracket,b);
    private static Formula PositiveStatement()
    {
        var E=I("E"); var P=I("P"); var J=I("J"); var D=I("D"); var cone=I("C"); var p=I("p");
        var f=I("f"); var a=I("a"); var b=I("b"); var X=I("X"); var i=I("i"); var JX=I("JX");
        var k=I("k"); var n=I("n"); var R=I("R"); var v=I("v"); var real=C("Real"); var complex=C("Complex");
        var K=C("originalCorner",i,JX,k); var F=C("cornerVectorRead",R,v);
        Formula Apply(Formula x)=>C("apply",F,x);
        Formula Op(Formula x)=>C("apply",C("cornerOp",R,x),v);
        Formula Sq(Formula x)=>C("pow",x,N(2));
        Formula Norm(Formula x)=>C("norm",x);
        Formula Re(Formula x)=>C("re",x);
        Formula Inner(Formula x,Formula y)=>C("inner",complex,x,y);
        Formula RJ(Formula x,Formula y)=>C("cornerJordan",R,x,y);
        Formula RD(Formula x,Formula y)=>C("cornerResponse",R,x,y);
        var baseTable=All("f",C("RealLinearMap",E,real),Imp(C("PositiveOn",f,cone),
            All("a",E,All("b",E,And(C("PosSemidef",C("originalTable",J,D,f,a,b)),
                C("Le",Sq(C("apply",f,C("apply",D,a,b))),
                    C("Subtract",Mul(C("apply",f,C("apply",J,a,a)),C("apply",f,C("apply",J,b,b))),
                        Sq(C("apply",f,C("apply",J,a,b))))))))));
        var vectors=And(All("a",K,Imp(C("Member",C("val",a),cone),C("Le",N(0),Apply(a)))),
            And(All("a",K,Eq(Inner(v,Op(a)),C("ofReal",Apply(a)))),
            And(Eq(Apply(C("CornerUnit",R)),Sq(Norm(v))),
            And(All("a",K,Eq(Apply(RJ(a,a)),Sq(Norm(Op(a))))),
            And(All("a",K,All("b",K,Eq(Apply(RJ(a,b)),Re(Inner(Op(a),Op(b)))))),
                All("a",K,All("b",K,
                    And(Eq(C("val",RJ(a,b)),C("apply",J,C("val",a),C("val",b))),
                    And(Eq(C("val",RD(a,b)),C("apply",D,C("val",a),C("val",b))),
                    And(C("PosSemidef",C("originalTable",C("cornerJordan",R),C("cornerResponse",R),F,a,b)),
                        C("Le",Sq(Apply(RD(a,b))),C("Subtract",Mul(Sq(Norm(Op(a))),Sq(Norm(Op(b)))),
                            Sq(Re(Inner(Op(a),Op(b))))))))))))))));
        var corners=All("X",I("Type"),Inst(C("NormedAddCommGroup",X),Inst(C("NormedSpace",real,X),
            All("i",C("RealLinearIsometry",E,X),All("JX",C("RealBilinearMap",X,X,X),
            All("k",E,All("n",I("Type"),Inst(C("Fintype",n),Inst(C("DecidableEq",n),
            All("R",C("ActualMatrixCorner",J,D,cone,i,JX,k,n),All("v",C("EuclideanSpace",complex,n),vectors)))))))))));
        var hypotheses=And(C("ExactCone",cone,p),C("AllOriginalTablesPositive",J,D,p));
        var body=All("J",C("RealBilinearMap",E,E,E),All("D",C("Function",E,E,E),
            All("C",C("Set",E),All("p",C("Function",P,C("RealLinearMap",E,real)),
                Imp(hypotheses,And(baseTable,corners))))));
        return All("E",I("Type"),All("P",I("Type"),
            Inst(C("NormedAddCommGroup",E),Inst(C("NormedSpace",real,E),body))));
    }
    private static Formula Statement()
    {
        var A=I("A"); var E=I("E"); var P=I("P"); var O=I("O"); var B=I("B"); var center=I("C");
        var chi=I("chi"); var x=I("x"); var y=I("y"); var X=I("X"); var Y=I("Y"); var delta=I("delta");
        var real=C("Real"); var complex=C("Complex");
        var zero=Imp(C("Subsingleton",A),And(All("a",E,Eq(I("a"),N(0))),
            All("a",E,All("b",E,Eq(C("D",O,I("a"),I("b")),N(0))))));
        var proper=All("chi",C("StarCharacter",center,complex),All("x",E,All("y",E,
            All("X",real,All("Y",real,All("delta",real,
                Imp(C("SectorCertificate",O,B,center,chi,x,y,X,Y,delta),
                    C("Nonempty",C("Realization",O,B,center,chi,x,y,X,Y,delta)))))))));
        var central=All("c",center,All("b",B,Eq(Mul(C("val",I("c")),C("val",I("b"))),
            Mul(C("val",I("b")),C("val",I("c"))))));
        var assumptions=And(C("PB",C("J",O),C("D",O)),And(C("BDerivedInterface",C("J",O),C("u",O),C("D",O)),
            And(C("Closed",center),And(C("Included",center,B),central))));
        var body=All("O",C("OriginalData",A,E,P),All("B",C("StarSubalgebra",complex,A),
            All("C",C("StarSubalgebra",complex,A),Imp(assumptions,And(zero,proper)))));
        body=Inst(C("CstarAlgebra",A),Inst(C("PartialOrder",A),Inst(C("StarOrderedRing",A),
            Inst(C("NormedAddCommGroup",E),Inst(C("NormedSpace",real,E),body)))));
        return All("A",I("Type"),All("E",I("Type"),All("P",I("Type"),body)));
    }
}
